const e="Parenting Skills Therapy | Michelle Barratt Psychology",t="Parenting can be rewarding, but it can also feel overwhelming when behavioural, emotional, or family challenges arise.",i='<!--$--><section class="bg-gradient-to-br from-plum to-rose text-white"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20"><div><nav aria-label="Breadcrumb" class="mb-6"><ol class="flex flex-wrap items-center gap-2 text-[12px] uppercase tracking-[0.14em] text-white/75"><li><a class="hover:text-white" href="/">Home</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li><a class="hover:text-white active" href="/therapy-services" data-status="active" aria-current="page">Therapy Services</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li class="text-white" aria-current="page">Parenting Skills Therapy</li></ol></nav><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-white/85 mb-3">Relationships &amp; Family</p><h1 class="text-white text-[32px] md:text-[44px] font-semibold leading-[1.08] max-w-3xl">Parenting Skills Therapy</h1><div class="h-[3px] w-16 bg-sun my-5" aria-hidden="true"></div><div class="max-w-2xl text-[16px] md:text-[17px] text-white/95 space-y-3"><p>Parenting can be rewarding, but it can also feel overwhelming when behavioural, emotional, or family challenges arise.</p><p>Michelle Barratt Psychology Administrative Services connects parents with experienced Brisbane psychologists and online Australia-wide practitioners who provide evidence-based parenting skills therapy, practical strategies, and compassionate support to help strengthen family relationships and build parenting confidence.</p></div><div class="mt-6 flex flex-wrap gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-white text-plum hover:bg-blush " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-white/70 text-white hover:bg-white/10 " href="/practitioners">See Practitioners</a></div></div></div></section><section class="bg-soft !py-0"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="py-14 md:py-16"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2020/10/parenting-skills-1.jpg" alt="Parenting Skills 1" class="w-full aspect-[16/9] max-h-[520px] object-cover rounded border border-lilac"/></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Parenting Skills Therapy</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology Administrative Services (MBP) provides a clinically informed administrative hub that acts as a compassionate first point of contact for families. We recognise that seeking help for parenting can feel overwhelming; our team is dedicated to ensuring you feel heard and supported as we handle the logistics of connecting you with independent Brisbane psychologists and allied health practitioners.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology (MBP) provides in-person therapy across Brisbane, and flexible online therapy Australia-wide, ensuring your journey to healing remains consistent and accessible.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How does MBP support your parenting journey?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Our role is to remove the administrative burden so parents can focus on building stronger, healthier relationships with their children. Through compassionate intake, professional coordination, referral support, and ongoing administrative assistance, MBP helps make the process of accessing parenting support straightforward and stress-free.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Whether you are seeking guidance for behavioural challenges, emotional regulation, anxiety, family conflict, developmental concerns, or parenting confidence, we help connect you with practitioners who can provide practical, evidence-based support.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What support does MBP provide?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Compassionate Intake</h3><p class="text-[15px] leading-relaxed text-ink/85">A supportive intake process ensures your concerns are heard and helps identify the most suitable therapeutic match.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Seamless Coordination</h3><p class="text-[15px] leading-relaxed text-ink/85">Scheduling for parent sessions, child consultations, and family appointments is managed to fit busy family life.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Clear Communication</h3><p class="text-[15px] leading-relaxed text-ink/85">MBP helps coordinate information and resources between families and practitioners throughout the care journey.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Referral Guidance</h3><p class="text-[15px] leading-relaxed text-ink/85">Professional assistance is available for Medicare, private health, and referral documentation requirements.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Ongoing Support</h3><p class="text-[15px] leading-relaxed text-ink/85">Families have access to a consistent administrative contact for questions relating to appointments and care pathways.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Flexible Access</h3><p class="text-[15px] leading-relaxed text-ink/85">Support is available through Brisbane-based appointments and online Australia-wide therapy options.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How do I get started?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are ready to resolve current challenges and strengthen your family&#x27;s dynamic, email us using the form below or contact us, and we will guide you through the process and help you find a suitable Brisbane psychologist or allied health practitioner who specialises in parenting support.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Explore Our Clinicians:</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You may also view our Practitioner Page and select the clinician of your choice.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Important safety note</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are in immediate danger, experiencing severe distress, or having thoughts of harming yourself, contact emergency services or a crisis service right away. If you are concerned but not in immediate danger, please mention this when you contact us so we can prioritise an appropriate, timely response.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">When can parenting skills therapy help?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Many parents seek support during periods of uncertainty, stress, or family change. Parenting skills therapy can help when children are experiencing behavioural difficulties, emotional challenges, anxiety, low self-esteem, conflict at home, adjustment issues, or difficulties at school.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Seeking support is not a sign of failure. In fact, many parents benefit from learning new strategies, gaining fresh perspectives, and building confidence in their parenting approach.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Issues families often seek support for</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting support may assist families experiencing:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Anxiety and emotional regulation difficulties • Low self-esteem and confidence concerns • Stress and family overwhelm • Challenging or disruptive behaviours • Tantrums and emotional outbursts • Defiant or oppositional behaviour • Family conflict and communication difficulties • Adjustment to change, separation, or life transitions • Self-harm concerns or emotional distress</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Support is tailored to the individual needs of both the child and the family.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Building your parenting toolkit</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting skills therapy is designed to equip parents with practical, evidence-based strategies that can be applied in everyday situations. Sessions often focus on understanding behaviour, improving communication, managing conflict, and strengthening parent-child relationships.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Depending on your family&#x27;s needs, practitioners may incorporate behavioural parenting strategies, Cognitive Behavioural Therapy (CBT), emotional regulation techniques, family therapy approaches, and developmental education.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What does parenting skills therapy focus on?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting support aims to strengthen both parenting confidence and family relationships.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Key areas commonly addressed include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Behavioural management strategies • Maintaining positive parent-child connections • Emotional regulation for parents and children • Understanding developmental stages • Building confidence and consistency • Conflict resolution and de-escalation skills • Creating calmer home environments • Strengthening communication within families</span></li></ul><figure class="my-9"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2026/05/38882.jpg" alt="38882" loading="lazy" class="w-full max-w-4xl aspect-[3/2] object-cover rounded border border-lilac"/></figure><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting challenges can sometimes leave families feeling overwhelmed, uncertain, or disconnected. Seeking support is not about being a perfect parent—it is about gaining practical tools, fresh perspectives, and professional guidance that help strengthen family relationships. With the right support, parents can build confidence, improve communication, manage challenging behaviours more effectively, and create a calmer, more positive home environment where both children and parents can thrive.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Supporting Stronger Family Relationships</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting can be one of the most rewarding experiences in life, but it can also be one of the most challenging. Every family experiences periods of stress, uncertainty, or conflict, particularly during developmental transitions or difficult life circumstances.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting skills therapy provides practical support that helps families navigate these challenges while maintaining positive relationships and promoting healthy emotional development for children.</p><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">1 Understand Behaviour</h3><p class="text-[15px] leading-relaxed text-ink/85">Learn how oppositional behaviour develops and identify patterns that may contribute to conflict within the home. Understanding the reasons behind your child&#x27;s reactions can help you respond more effectively and reduce frustration for everyone involved.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">2 Consistent Boundaries</h3><p class="text-[15px] leading-relaxed text-ink/85">Establish clear expectations, routines, and consequences that provide children with structure and predictability. Consistency helps reduce confusion, supports positive behaviour, and creates a more stable family environment.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">3 Parent Empowerment</h3><p class="text-[15px] leading-relaxed text-ink/85">Develop evidence-based strategies that increase confidence when responding to challenging behaviour. Parents learn practical techniques that encourage cooperation while maintaining a positive and supportive relationship with their child.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">4 Conflict Reduction</h3><p class="text-[15px] leading-relaxed text-ink/85">Learn practical techniques for reducing power struggles and de-escalating difficult situations before they become overwhelming. These strategies can help create calmer interactions and improve communication within the family.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">5 Collaborative Problem Solving</h3><p class="text-[15px] leading-relaxed text-ink/85">Build skills that encourage children and parents to work together when addressing challenges. This approach helps reduce opposition, promotes mutual respect, and strengthens family relationships over time.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Contact Us on the Email Form Below</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please be advised that you&#x27;ll receive a response within 24 to 48 hours.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If in crisis, please call 000.</p></div></section><section class="bg-lilac !py-14"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-4">More in <!-- -->Relationships &amp; Family</p><ul class="flex flex-wrap gap-3"><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/couples">Couples Therapy<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/family-therapy">Family Therapy<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/divorce-separation">Separation &amp; Divorce<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/conflict-management">Conflict Management<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/domestic-violence">Domestic Violence Support<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li></ul></div></section><section class="bg-blush"><div class="mx-auto max-w-4xl px-5 py-14 md:py-16 text-center"><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-2.5">Take the first step</p><h2 class="text-[30px] md:text-[40px] font-semibold leading-[1.1]">Ready to Take the First Step?</h2><div class="h-[3px] w-14 bg-sun mt-4 mx-auto" aria-hidden="true"></div><p class="mt-5 text-[17px]">Seeking support can feel overwhelming, but you do not have to navigate life&#x27;s challenges alone. Our administration team can help answer your questions, explain appointment options and connect you with a suitable practitioner.</p><p class="mt-3">Prefer to call? Phone our administration team on <a class="text-ocean underline underline-offset-4 font-medium" href="tel:0731850040">07 3185 0040</a>.</p><div class="mt-7 flex flex-wrap justify-center gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-rose text-white hover:bg-[#9d2a59] " href="/practitioners">Book Online</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-ocean text-white hover:bg-[#095a6f] " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-plum text-plum hover:bg-lilac  active" href="/therapy-services" data-status="active" aria-current="page">Explore Services</a></div><p class="mt-5 text-sm text-ink/70">If in crisis, please call 000.</p></div></section><!--/$-->',a={title:e,description:t,html:i};export{a as default,t as description,i as html,e as title};
